209	  private readonly entries = new Map<string, V>();
210	  constructor(private readonly limit: number) {}
211	
212	  get(key: string): V | undefined {
213	    return this.entries.get(key);
214	  }
215	
216	  set(key: string, value: V): void {
217	    this.entries.delete(key);
218	    this.entries.set(key, value);
219	    while (this.entries.size > this.limit) {
220	      this.entries.delete(this.entries.keys().next().value!);
221	    }
